"""Build the third workshop: public activities, original starters, and handouts."""
import json,csv,io,zipfile
from pathlib import Path
from html import escape as e

def build_cooperative(api):
 R=api['R'];page,heading,section,link,ul,challenge,countdown=[api[k] for k in ['page','heading','section','link','ul','challenge','countdown']];slug='play-explore-explain';SP='sessions/'+slug+'/';DD='downloads/'+slug+'/';out=R/DD;out.mkdir(parents=True,exist_ok=True)
 d=json.loads((R/'data/cooperative-learning.json').read_text());s=next(x for x in api['DATA']['sessions'] if x['id']==slug)
 def nav():return '<nav class="session-nav" aria-label="Play, Explore, Explain session"><div class="container">'+''.join('<a href="@@'+SP+p+'">'+label+'</a>' for p,label in [('index.html','Overview'),('participate.html','Play and participate'),('activities.html','Explore the tools'),('toolkit.html','Toolkit and downloads'),('presenter-guide.html','Presenter guide')])+'</div></nav>'
 def show(file,title,body):page(SP+file,title,nav()+body,'sessions')
 agenda='<ol class="agenda">'+''.join('<li><time>'+str(a['start'])+'–'+str(a['end'])+' min</time><div><strong>'+e(a['title'])+'</strong><p>'+e(a['prompt'])+'</p></div></li>' for a in d['agenda'])+'</ol>'
 roles='<div class="grid two">'+''.join('<article class="card"><h3>'+e(r['name'])+'</h3><p>'+e(r['task'])+'</p></article>' for r in d['roles'])+'</div><p>Work in groups of three or four. With three, combine Navigator and Connector. Swap roles in round two; a role never stops anyone else from thinking or explaining.</p>'
 show('index.html',s['title'],heading('Cooperative learning',s['title'],'Let’s play, listen to one another, and make the thinking visible.')+section('<div class="split"><div class="prose"><h2>What happens after the game?</h2><p>'+e(s['fullDescription'])+'</p><p><strong>Bring:</strong> '+e(s['technology'])+'</p><div class="actions">'+link('participate.html#play','Start with concept Bingo')+link('presenter-guide.html','Open presenter guide','button ghost')+'</div><h2>Learning outcomes</h2>'+ul(s['learningObjectives'])+'<h2>Success criteria</h2>'+ul(s['successCriteria'])+'</div><aside class="card"><h2>Our fifty-minute plan</h2>'+agenda+'</aside></div>')+section('<div class="grid two"><div><img class="coop-photo" src="@@assets/images/cooperative-explanation-photo.webp" width="1400" height="788" alt="Illustrative educators using sequence cards and a tablet to explain an idea together"></div><div><h2>A shared task needs every voice.</h2><p>We’ll give everyone quiet thinking time, a chance to explain, and a reason to listen. The goal is a shared explanation you can all give—not a race to let one person finish.</p><p>You can share a device, speak, write, or ask a partner to read your contribution. Printed cards and prompts are in the toolkit if connectivity is unreliable.</p></div></div><p class="small muted">'+e(d['imageDisclosure'])+'</p>','pale'))
 def toolcard(t):
  return '<article class="card" id="'+t['id']+'"><p class="eyebrow">Round '+('one' if t['round']==1 else 'two')+'</p><h3>'+e(t['name'])+'</h3><p><strong>Why try it?</strong> '+e(t['purpose'])+'</p><p>'+e(t['task'])+'</p><p><strong>Make or share:</strong> '+e(t['product'])+'</p><p><strong>Listen for:</strong> '+e(t['listenFor'])+'</p><div class="actions">'+link(t['url'],'Open '+t['name']+' ↗','button small',True)+(link(t['secondUrl'],'Open Bingo Caller ↗','button ghost small',True) if t.get('secondUrl') else '')+link('@@'+DD+t['starter'],'Get sample content','button ghost small')+'</div></article>'
 paths='<div class="grid"><article class="card"><h3>Review and recall</h3><p>Round one: Bingo. Round two: Quiz and Flashcard Studio.</p><p>Ask everyone to retrieve before comparing answers.</p></article><article class="card"><h3>Puzzles and reasoning</h3><p>Round one: Meme Puzzle. Round two: Fortune Wheel.</p><p>After a reveal or solved phrase, ask for evidence and an example.</p></article><article class="card"><h3>Create and explain</h3><p>Round one: Story Wheel. Round two: Dicebreaker Creator.</p><p>Explain a sequence, then use a follow-up to extend an idea.</p></article></div>'
 evidence='<div class="callout"><h3>Read the evidence with care.</h3><p>Structured group tasks need a common purpose, supported participation, and attention to who contributes. The EEF review distinguishes this from simply sitting together. We use peer explanations and checks to surface reasoning, not to claim that any tool automatically produces deeper learning.</p><p>The IES practice guide discusses retrieval and explanatory questions. These short conference activities illustrate routines; they do not establish learning gains or numerical effects for SplatWorks tools.</p>'+''.join('<p><a href="'+x['url']+'" target="_blank" rel="noopener noreferrer">'+e(x['name'])+' ↗</a></p>' for x in d['sources'])+'<p class="small">Sources checked '+d['verifiedDate']+'. No unverified effect sizes are published.</p></div>'
 show('activities.html','Explore six tools with a learning purpose',heading('Group exploration','Choose a path. Make the thinking visible.','Try one activity in each eight-minute round. Keep the shared goal, rotate roles, and save one classroom idea.')+section(paths+'<h2>Our exploration routine</h2><ol><li>One quiet minute: everyone predicts or drafts an answer.</li><li>Four minutes: try the shared task; change the person using the device.</li><li>Two minutes: explain, ask a follow-up, and check the reasoning.</li><li>One minute: record a classroom idea and one piece of evidence.</li></ol><h2>Round one · minutes eighteen to twenty-six</h2><div class="grid">'+''.join(toolcard(t) for t in d['tools'] if t['round']==1)+'</div><h2>Round two · minutes twenty-six to thirty-four</h2><div class="grid">'+''.join(toolcard(t) for t in d['tools'] if t['round']==2)+'</div>'+evidence))
 cells=[]
 for i,term in enumerate(d['terms']):
  if i==4:cells.append('<span class="coop-free">FREE<br>Explain a choice</span>')
  cells.append('<button type="button" class="coop-cell" aria-pressed="false">'+e(term['term'])+'</button>')
 bingo='<div class="coop-game" id="coop-game"><h3>Your concept Bingo card</h3><p>Choose a clue with the group, then mark the matching concept. Before claiming a line, explain the matches. Winning is optional; explaining is the point.</p><div class="coop-bingo" aria-label="Concept Bingo card">'+''.join(cells)+'</div><div class="actions"><button type="button" id="coop-next-clue">Next clue</button><button type="button" class="button ghost" id="coop-reveal-term">Check the term</button><button type="button" class="button ghost" id="coop-new-card">New card and reset clues</button></div><p id="coop-clue" class="prompt" role="status">Choose Next clue when you’re ready.</p><p id="coop-term" role="status"></p><p id="coop-line" role="status"></p><details><summary>All clues and explanations · also works on paper</summary><ol>'+''.join('<li>'+e(t['clue'])+' <strong>'+e(t['term'])+'</strong></li>' for t in d['terms'])+'</ol></details><p class="small">Cards and marks are independent on each device; nothing is sent to a live room. Bingo Caller can project a custom call list. Its room name does not synchronize separate attendee devices without an added relay.</p></div>'
 fields=''.join('<label for="coop-note-'+str(i)+'">'+e(label)+'</label><textarea id="coop-note-'+str(i)+'" data-label="'+e(label)+'" maxlength="2500"></textarea>' for i,label in enumerate(d['planningFields']))
 form='<form class="reflection" id="coop-notes"><p>Your notes stay in this page’s memory. Copy or print before leaving; reloading clears them.</p>'+fields+'<div class="actions"><button type="button" id="coop-copy">Copy our adaptation</button><button type="button" class="button ghost" id="coop-print">Print our adaptation</button><button type="reset" class="button ghost">Clear notes</button></div><p id="coop-notes-status" role="status"></p></form>'
 exit=challenge('coop-exit-goal','Which change makes the game more cooperative?',['Give the fastest person every turn','Give the group a shared explanation and invite each person to contribute','Add more points without changing the task'],'A common outcome plus each person’s contribution gives the group a reason to listen and explain. Points alone do not structure cooperative learning.')+challenge('coop-exit-recall','When does the quiz invite retrieval practice?',['When you answer from memory before looking back','When you copy the displayed answer','Only when the quiz has a leaderboard'],'Try recalling before looking. Then check the explanation, correct errors, and revisit the idea later.')+challenge('coop-exit-feedback','What makes the check formative?',['The activity records a score','You use an explanation or misconception to choose feedback and the next task','Everyone finishes the activity'],'Use evidence of learner thinking to adjust instruction, provide a specific cue, and invite another attempt. Completion alone is not enough.')
 sections=[('play','Let’s start with a game',bingo),('connect','What makes the learning cooperative?',roles+'<div class="callout"><h3>Try → explain → question → revise</h3><p>Before clicking, give each person thinking time. After a choice, ask “Why does that fit?” Invite someone else to extend or question the explanation, then revise together.</p></div>'),('explore','Try two activities together',paths+'<div class="actions">'+link('activities.html','Open the tool tasks and starter files')+'</div>'+countdown()),('share','Show us what you discovered','<ol><li>Use one minute each to explain to a nearby group: “We tried ____. Learners would explain ____. We’d look for ____.”</li><li>Ask one follow-up about the evidence or participation.</li><li>We’ll hear up to three short examples from the room.</li></ol><p>You don’t need to move seats or share anyone’s personal information. Speak, write, or ask a partner to share your contribution.</p>'),('adapt','Make one activity useful for your learners',form),('check','Check what you can now explain',exit)]
 show('participate.html','Play and participate',heading('Participate','Let’s play, explore, and explain together.','Open the game, follow the group routine, and keep a classroom idea you can use.')+section(''.join('<section class="activity" id="'+id+'"><p class="eyebrow">'+str(d['agenda'][i]['start'])+'–'+str(d['agenda'][i]['end'])+' minutes</p><h2>'+title+'</h2>'+content+'</section>' for i,(id,title,content) in enumerate(sections))))
 # Verified tool import formats: plain newline lists, question/answer CSV, and Quiz CSV.
 (out/'bingo-terms.txt').write_text('\n'.join(t['term'] for t in d['terms'])+'\n')
 (out/'dice-prompts.txt').write_text('\n'.join(['Explain one choice your group made.','Give an example that would help a learner.','What evidence would change your mind?','Ask a partner to extend your explanation.','Describe a misconception and a helpful cue.','How would you adapt this for another subject?'])+'\n')
 (out/'fortune-phrases.txt').write_text('EXPLAIN YOUR REASONING\nEVERY VOICE CONTRIBUTES\nRECALL BEFORE YOU REVEAL\nUSE EVIDENCE\nREVISE AFTER FEEDBACK\n')
 (out/'story-sequence.txt').write_text('Story Wheel example: A seed grows\nEvent one: A seed receives water under suitable conditions.\nEvent two: A root emerges and a shoot begins to grow.\nEvent three: Leaves develop and the young plant can use light.\nAsk: Why does this order make sense? What information would help you explain the process?\nAdapt the science detail and language for your learners.\n')
 rows=[('What do we call recalling before looking back?','Retrieval practice','Copying','Guessing only','Finishing first','multiple-choice',1,'Recall before viewing an answer, then check and revise.'),('What helps a group work cooperatively?','A shared goal and each person contributing','One person doing all the work','More points only','Silent copying','multiple-choice',1,'A shared explanation needs everyone’s thinking.'),('What makes a check formative?','Using evidence to decide feedback or next teaching','Only recording a score','Finishing the game','Adding a timer','multiple-choice',1,'Use what learners say or do to choose the next response.')]
 with (out/'review-quiz.csv').open('w',newline='') as f:w=csv.writer(f);w.writerow(['question','answer','wrong1','wrong2','wrong3','type','points','notes']);w.writerows(rows)
 with (out/'meme-review.csv').open('w',newline='') as f:w=csv.writer(f);w.writerow(['question','answer']);w.writerows([(t['clue'],t['term']) for t in d['terms'][:4]])
 # Selectable-text PDFs and semantic HTML alternatives share the same content.
 blocks={
 'session-handout':('Play, Explore, Explain · quick reference',[('Our workshop',s['title']+'\n'+s['technology']),('Our fifty-minute route','\n'.join(str(a['start'])+'–'+str(a['end'])+': '+a['title'] for a in d['agenda'])),('Six tools, clear purposes','\n'.join(t['name']+'\n'+t['url']+'\n'+t['purpose'] for t in d['tools'])),('Start here','https://mglearn.github.io/tcea27/'+SP),('Check your design','Shared outcome; each person thinks and contributes; explanation and evidence; a useful feedback cue and revision.')]),
 'exploration-sheet':('Our group exploration sheet',[('Choose two tools','Round one: Bingo, Meme Puzzle, or Story Wheel.\nRound two: Quiz and Flashcard Studio, Fortune Wheel, or Dicebreaker Creator.'),('Give everyone a way in','\n'.join(r['name']+': '+r['task'] for r in d['roles'])),('Eight-minute round','Think for one minute; try for four; explain and check for two; record for one. Swap roles in round two.'),('What we tried','Tool and shared task: _______________________________________\nWhat each person explained: _________________________________\nWhat we noticed about learning: ______________________________'),('Share one useful discovery','We tried ____. Learners would explain ____. We would look for ____.\nOne question or adaptation: __________________________________')]),
 'adaptation-template':('Make it work for your classroom',[(label,'________________________________________________________\n________________________________________________________') for label in d['planningFields']]+[('A small quality check','Can each learner explain a choice? Does the task need contributions from others? What feedback will you offer, and when can learners revise? Choose supports for speech, writing, language, reading, and device access.')]),
 'bingo-cards':('Concept Bingo · paper cards and clue guide',[('How we’ll play','Use one card per person or group. Read a clue, think quietly, compare reasons, and mark the matching term. Explain a row before claiming it. Shared reasoning matters more than speed.'),('Card A','Retrieval practice | Peer explanation | Evidence\nFeedback | FREE: explain a choice | Reflection\nShared goal | Formative assessment | Elaboration'),('Card B','Elaboration | Evidence | Shared goal\nPeer explanation | FREE: explain a choice | Retrieval practice\nReflection | Feedback | Formative assessment'),('Clues and explanation key','\n'.join(str(i+1)+'. '+t['clue']+' Answer: '+t['term'] for i,t in enumerate(d['terms']))),('Teacher setup','Paste bingo-terms.txt into Bingo Card Generator; choose 3×3 and a free center. Printed cards or this local page work independently; do not assume cross-device room synchronization.')])}
 docs=[]
 from reportlab.platypus import SimpleDocTemplate,Spacer
 from reportlab.pdfgen import canvas
 from functools import partial
 for key,(title,parts) in blocks.items():
  story=[api['para']('TCEA 2027 | MIGUEL GUHLIN','Small27'),api['para'](title,'Title27')];html=''
  for sub,text in parts:
   story.append(api['para'](sub,'Section27'));html+='<h2>'+e(sub)+'</h2>'
   if sub in ['Card A','Card B']:
    from reportlab.platypus import Table,TableStyle
    from reportlab.lib import colors
    rows=[[api['para'](cell.strip()) for cell in line.split('|')] for line in text.split('\n')]
    table=Table(rows,colWidths=[170]*3,rowHeights=[72]*3);table.setStyle(TableStyle([('GRID',(0,0),(-1,-1),1,colors.HexColor('#28657a')),('BACKGROUND',(1,1),(1,1),colors.HexColor('#fff0cd')),('VALIGN',(0,0),(-1,-1),'MIDDLE'),('LEFTPADDING',(0,0),(-1,-1),8)]));story.append(table)
    html+='<table><caption>'+e(sub)+'</caption><tbody>'+''.join('<tr>'+''.join('<td>'+e(cell.strip())+'</td>' for cell in line.split('|'))+'</tr>' for line in text.split('\n'))+'</tbody></table>'
   else:
    for line in text.split('\n'):story.append(api['para'](line));html+='<p>'+e(line)+'</p>'
  story.append(api['para']('Original workshop activities by Miguel Guhlin / MG Learn. Reuse and adapt with attribution. Tool links and evidence sources retain their respective terms. TCEA 2027.','Small27'))
  SimpleDocTemplate(str(out/(key+'.pdf')),pagesize=(612,792),rightMargin=45,leftMargin=45,topMargin=42,bottomMargin=50,title=title,author='Miguel Guhlin / MG Learn',invariant=1).build(story,onFirstPage=api['footer'],onLaterPages=api['footer'],canvasmaker=partial(canvas.Canvas,invariant=1))
  page(DD+key+'.html',title,heading('Workshop handout',title,'Read, print, or adapt this resource.')+section('<div class="prose">'+html+link(key+'.pdf','Download PDF')+'</div>'),'downloads');docs.append('<article class="download"><div><h3>'+e(title)+'</h3></div><div class="actions">'+link('@@'+DD+key+'.pdf','Download PDF','button small')+link('@@'+DD+key+'.html','Read HTML','button ghost small')+'</div></article>')
 starterlist='<ul>'+''.join('<li>'+link('@@'+DD+t['starter'],t['name']+' · sample content','')+'</li>' for t in d['tools'])+'</ul>'
 show('toolkit.html','Cooperative learning toolkit',heading('Toolkit','Keep the activity. Adapt the teaching.','Take the prompts, starter files, and planning sheets back to your classroom.')+section('<div class="download-list">'+''.join(docs)+'</div><h2>Starter files for all six tools</h2>'+starterlist+'<p>Use the task cards for the exact paste/import steps. These are original workshop samples, not copied tool libraries. You’ll still need connectivity to open the external tools.</p>'+evidence))
 p=R/'downloads.html';text=p.read_text();addition=section('<h2>Play, Explore, Explain resources</h2><p>Take the group sheet, concept Bingo cards, classroom adaptation template, and six tool starter files.</p>'+link(SP+'toolkit.html','Open the cooperative learning toolkit'));p.write_text(text.replace('<section class="print-reflection',addition+'<section class="print-reflection',1))
 print('Built cooperative learning pages, six starter files, and four PDF/HTML handouts.')
